-- APEX SPORT update for an EXISTING database: 12 new photo products (30-41) and removal of the old products with drawn pictures.
-- Run AFTER supabase-update-descriptions.sql. SQL Editor -> New query -> paste everything -> Run. Safe to run again.
-- (New installs do not need this file: supabase.sql already contains everything.)

-- 1) New colours
on conflict (hex) do nothing;

-- 2) New products
on conflict (id) do update set cat = excluded.cat, sub = excluded.sub, art = excluded.art, mat = excluded.mat, price = excluded.price,
  sizes = excluded.sizes, colors = excluded.colors, name = excluded.name, is_new = excluded.is_new, photos = excluded.photos, descr = excluded.descr;

-- 3) Remove the products that only had drawn pictures (ids 1,4,5,6,7,8,10,11,12,13)
delete from shop_products where id in (1, 4, 5, 6, 7, 8, 10, 11, 12, 13);
